#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> d(61, 0);
    vector<int> e(61, 0);

    for (int i = 0; i < n; ++i) {
        int m;
        char l;
        cin >> m >> l;
        if (l == 'D') {
            d[m]++;
        } else {
            e[m]++;
        }
    }

    int total_pares = 0;
    for (int m = 30; m <= 60; ++m) {
        total_pares += min(d[m], e[m]);
    }

    cout << total_pares << "\n";

    return 0;
}
